LIN = "A ← [3, 8, 1, 9, 4, 7, 2]\ni ← 0\nwhile i < len(A) and A[i] ≠ x do\n  i ← i + 1\nend\nif i = len(A) then\n  return -1\nend\nreturn i"
BIN = ("A ← [2, 5, 8, 12, 16, 23, 38, 41, 57, 60, 72, 85, 91, 99, 104]\nlo ← 0\nhi ← len(A) - 1\nwhile lo ≤ hi do\n  mid ← (lo + hi) div 2\n"
       "  if A[mid] = x then\n    return mid\n  end\n  if A[mid] < x then\n    lo ← mid + 1\n  else\n    hi ← mid - 1\n  end\nend\nreturn -1")
COLLATZ = "c ← 0\nwhile n ≠ 1 do\n  if n mod 2 = 0 then\n    n ← n div 2\n  else\n    n ← 3 * n + 1\n  end\n  c ← c + 1\nend\nreturn c"

